 for(const k of ['x','y','z','rotation','width','height','depth'])$('piece-'+k).onchange=()=>{const el=$('piece-'+k);if(el.value===''||!el.checkValidity()){syncInspector();return;}change(()=>{piece()[k]=Number(el.value);if(['x','y','z','rotation'].includes(k))piece().placement='custom';});};
 $('piece-visible').onchange=()=>change(()=>piece().visible=$('piece-visible').checked,{tree:true});$('led-color').onchange=()=>patchLED({color:$('led-color').value});$('led-brightness').oninput=()=>$('brightness-value').textContent=$('led-brightness').value+' %';$('led-brightness').onchange=()=>patchLED({brightness:Number($('led-brightness').value)});$('led-on').onchange=()=>patchLED({on:$('led-on').checked});
 for(const k of ['offsetX','offsetY','offsetZ','scale','thickness'])$('led-'+k).onchange=()=>{const el=$('led-'+k);if(el.value===''||!el.checkValidity()){syncInspector();return;}patchLED({[k]:Number(el.value)});};
